import unittest
from candidate import filter_by_substring

class TestFilterBySubstring(unittest.TestCase):
    def test_filter_normal_case_with_matches(self):
        self.assertEqual(filter_by_substring(['abc', 'bacd', 'cde', 'array'], 'a'), ['abc', 'bacd', 'array'])

    def test_filter_normal_case_no_matches(self):
        self.assertEqual(filter_by_substring(['bcd', 'def'], 'a'), [])

    def test_filter_empty_input_list(self):
        self.assertEqual(filter_by_substring([], 'a'), [])

    def test_filter_substring_at_start(self):
        self.assertEqual(filter_by_substring(['abc', 'def'], 'a'), ['abc'])

    def test_filter_substring_at_end(self):
        self.assertEqual(filter_by_substring(['abc', 'def'], 'f'), ['def'])

    def test_filter_substring_in_middle(self):
        self.assertEqual(filter_by_substring(['abc', 'def'], 'b'), ['abc'])

    def test_filter_empty_substring_returns_all(self):
        self.assertEqual(filter_by_substring(['abc', 'def'], ''), ['abc', 'def'])

    def test_filter_none_strings_raises_type_error(self):
        with self.assertRaises(TypeError):
            filter_by_substring(None, 'a')

    def test_filter_none_substring_raises_type_error(self):
        with self.assertRaises(TypeError):
            filter_by_substring(['abc'], None)

    def test_filter_non_list_strings_raises_type_error(self):
        with self.assertRaises(TypeError):
            filter_by_substring(5, 'a')

    def test_filter_single_element_list(self):
        self.assertEqual(filter_by_substring(['abc'], 'a'), ['abc'])

    def test_filter_case_sensitivity(self):
        self.assertEqual(filter_by_substring(['ABC', 'abc'], 'a'), ['abc'])
